from pathlib import Path
from html import escape

views = [('inicio','Inicio'),('estudio','Estudio'),('tareas','Tareas'),('notas','Notas'),('musica','Música'),('planificacion','Planificador'),('cursos','Cursos'),('curso_detalle','Curso'),('ia','Charvis'),('ajustes','Sistema')]
details = [('curso','Curso · selector de prioridad y tarjetas de apuntes'),('apunte','Mis apuntes · edición'),('curso-900','Curso · vista compacta de escritorio'),('apunte-900','Apuntes · vista compacta de escritorio'),('sistema','Charvis desactivado · interruptor en Sistema'),('evento-1440','Nuevo evento · escritorio'),('evento-420','Nuevo evento · ventana estrecha'),('sesion','Nueva sesión · estilo de referencia')]
figures = ''.join(f'<figure><a href="qa-6261-{name}.png" target="_blank" rel="noopener"><img src="qa-6261-{name}.png" loading="lazy" decoding="async" alt="{escape(label)}"></a><figcaption>{escape(label)}</figcaption></figure>' for name,label in details + views)
html = '''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APHEKA 6.26.1 · revisión visual</title><style>body{margin:0;background:#111315;color:#e3e6e7;font:15px/1.65 system-ui,sans-serif}main{max-width:1460px;padding:42px clamp(18px,4vw,64px);margin:auto}h1{font-weight:550;letter-spacing:-.04em;font-size:clamp(28px,4vw,44px);margin:0 0 10px}p{color:#a7b0b5;max-width:85ch}nav{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0 34px}a{color:#bad2c5;text-decoration:none}nav a{padding:9px 14px;border:1px solid #343b40;border-radius:7px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,470px),1fr));gap:24px}figure{margin:0;border:1px solid #2c3338;border-radius:10px;overflow:hidden;background:#181c1f}img{display:block;width:100%;height:350px;object-fit:contain;object-position:top;background:#090a0b}figcaption{padding:14px 18px;color:#d3dcda;font-size:13px}a:focus-visible{outline:2px solid #bad2c5;outline-offset:3px}@media(max-width:600px){img{height:260px}}</style><main><h1>APHEKA 6.26.1</h1><p>Charvis se desactiva con clic derecho y vuelve desde Sistema. Escritura sin marco de foco interior, selector de prioridad propio, apuntes más claros y Nuevo evento con el estilo de las sesiones. Capturas con datos aislados de prueba; pulsa una imagen para verla completa.</p><nav><a href="APHEKA_6.26.1_Instalador_x64.exe">Instalador 6.26.1</a><a href="../docs/APHEKA-6.26.1.md">Cambios y verificación</a></nav><div class="grid">''' + figures + '</div></main></html>'
Path('release/qa-6261-gallery.html').write_text(html, encoding='utf-8')
